{
  "findings": [
    {
      "check_id": "CKV_AWS_2",
      "title": "Ensure ALB protocol is HTTPS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The load balancer listener is configured to use HTTP on port 80, which transmits data in cleartext and exposes it to interception or modification. It should be updated to use HTTPS with a valid SSL certificate."
    },
    {
      "check_id": "CKV_AWS_103",
      "title": "Ensure that load balancer is using at least TLS 1.2",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "Since the listener is currently HTTP, it does not enforce any TLS security policy. When migrating to HTTPS, an explicit `ssl_policy` (e.g., ELBSecurityPolicy-TLS-1-2-2017-01) must be defined to ensure modern encryption standards are used."
    }
  ],
  "patched_code": "resource \"aws_lb_listener\" \"webserver_listner\" {\n  load_balancer_arn = aws_lb.levelup-load-balancer.arn\n  port              = \"443\"\n  protocol          = \"HTTPS\"\n  ssl_policy        = \"ELBSecurityPolicy-TLS-1-2-2017-01\"\n  certificate_arn   = var.acm_certificate_arn # Requires a valid ACM certificate ARN variable to be defined elsewhere\n  default_action {\n    target_group_arn = aws_lb_target_group.load-balancer-target-group.arn\n    type             = \"forward\"\n  }\n}",
  "fix_summary": "Changed the listener protocol from HTTP to HTTPS, updated the port to 443, added a secure TLS 1.2+ SSL policy, and included a placeholder for the required SSL certificate ARN. Note: You must define the `acm_certificate_arn` variable or replace it with your actual certificate ARN for this code to apply successfully."
}
